logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)


def _hash_password(password):
    """Retourne un condensat SHA-256 du mot de passe."""
    return hashlib.sha256(password.encode("utf-8")).hexdigest()


def get_user(name):
    """Retourne les lignes de la table users correspondant au nom donné.

    La requête est paramétrée pour prévenir toute injection SQL.
    """
    if not isinstance(name, str) or not name.strip():
        raise ValueError("Le nom d'utilisateur est invalide.")

    with sqlite3.connect(DB_PATH) as conn:
        rows = conn.execute(
            "SELECT * FROM users WHERE name = ?", (name.strip(),)
        ).fetchall()
    return rows


def login(name, password):
    """Authentifie un utilisateur par nom et mot de passe.

    La comparaison du mot de passe est faite sur des condensats hachés,
    avec une comparaison à temps constant (hmac.compare_digest).
    """
    if not isinstance(name, str) or not name.strip():
        raise ValueError("Le nom d'utilisateur est invalide.")
    if not isinstance(password, str) or not password:
        raise ValueError("Le mot de passe est invalide.")

    try:
        expected = _hash_password(ADMIN_PASSWORD)
        provided = _hash_password(password)
        if hmac.compare_digest(provided, expected):
            return get_user(name)
    except sqlite3.Error as exc:
        logger.error("Erreur base de données lors du login : %s", exc)
        raise
    except Exception as exc:  # noqa: BLE001 - journalise et remonte l'erreur
        logger.error("Erreur inattendue lors du login : %s", exc)
        raise
    return None


if __name__ == "__main__":
    print(login(input("name: "), input("password: ")))
